/* i18n.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function install(P) {


  function pt(key, vars) {
    const value = P.PLAYER_I18N[P.playerLanguage]?.[key] ?? P.PLAYER_I18N.ru[key] ?? key;
    if (!vars) return value;
    return value.replace(/\{(\w+)\}/g, (match, name) =>
      Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match);
  }

  // menu.js owns the site-wide RU/EN switch and announces it with this event.
  // The player is injected outside [data-i18n] markup, so it translates itself.
  function setPlayerLanguage(language) {
    const next = language === "en" ? "en" : "ru";
    if (next !== P.playerLanguage) P.playerLanguage = next;
    P.applyPlayerLanguage();
  }

  function applyPlayerLanguage() {
    document.querySelectorAll("[data-player-i18n]").forEach((el) => {
      el.textContent = P.pt(el.dataset.playerI18n);
    });
    document.querySelectorAll("[data-player-i18n-aria-label]").forEach((el) => {
      el.setAttribute("aria-label", P.pt(el.dataset.playerI18nAriaLabel));
    });
    document.querySelectorAll("[data-player-i18n-title]").forEach((el) => {
      el.setAttribute("title", P.pt(el.dataset.playerI18nTitle));
    });
    // The settings form contains many static strings, so the simplest reliable
    // approach is to rebuild it from the current dictionary and re-sync values.
    document.querySelectorAll("[data-player-settings-mount]").forEach((mount) => {
      mount.innerHTML = P.settingsFormHtml();
    });
    P.syncProgramLockUi();
    P.syncSettingsUI();
    P.setFxRendering(false, P.fxRenderFailed);
    P.applyShuffle();
    P.applyRepeat();
    P.updateMuteState();
    P.renderQueue();
    if (P.state.current) P.renderMetadata();
    else P.$("playerTitle").textContent = P.pt("nothingPlaying");
    const loadingText = document.querySelector(".player-loading-text");
    if (loadingText) loadingText.textContent = P.pt("loading");
  }
  Object.assign(P, { pt, setPlayerLanguage, applyPlayerLanguage });
}
